<div class="relative" @keydown.escape.window="$wire.set('open', false)">
    <button type="button" wire:click="toggle" aria-label="Notifications{{ $unreadCount ? ', '.$unreadCount.' unread' : '' }}" aria-controls="notification-menu" aria-expanded="{{ $open ? 'true' : 'false' }}" class="relative inline-flex size-10 items-center justify-center rounded-md border border-line bg-white text-ink-700 hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-brand-700"><svg aria-hidden="true" class="size-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path stroke-linecap="round" stroke-linejoin="round" d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>@if($unreadCount)<span class="absolute -right-1 -top-1 grid min-h-5 min-w-5 place-items-center rounded-full bg-brand-700 px-1 text-[10px] font-bold text-white">{{ $unreadCount > 9 ? '9+' : $unreadCount }}</span>@endif</button>
    @if($open)<section id="notification-menu" class="absolute right-0 z-50 mt-2 w-[min(22rem,calc(100vw-2rem))] rounded-xl border border-line bg-white p-4 shadow-float" aria-label="Recent notifications" aria-live="polite"><div class="flex items-center justify-between gap-3"><h2 class="font-semibold text-ink-950">Notifications</h2>@if($unreadCount)<button type="button" wire:click="markAllRead" class="text-xs font-semibold text-brand-700 hover:underline">Mark all read</button>@endif</div>@if($notifications->isEmpty())<p class="py-7 text-center text-sm text-ink-500">You’re all caught up.</p>@else<ul class="mt-3 divide-y divide-line">@foreach($notifications as $notification)<li class="py-3"><a wire:click.prevent="visit('{{ $notification->id }}')" href="{{ $notification->safe_url ?? '#' }}" class="block rounded-sm text-sm leading-5 {{ $notification->read_at ? 'text-ink-600' : 'font-semibold text-ink-950' }} hover:text-brand-700 focus-visible:outline-2 focus-visible:outline-brand-700">{{ $notification->data['message'] ?? 'You have a new update.' }}<time class="mt-1 block text-xs font-normal text-ink-500" datetime="{{ $notification->created_at->toAtomString() }}">{{ $notification->created_at->diffForHumans() }}</time></a></li>@endforeach</ul>@endif</section>@endif
</div>
